import { sql } from "drizzle-orm";
import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { createInsertSchema, createSelectSchema } from "drizzle-orm/valibot";
import * as v from "valibot";

import { brand } from "./brand";
import type { Brand } from "./brand";
import { files } from "./files";

/**
 * The facilities showcase on `/academics`: "Where Aloysians learn & grow".
 *
 * Replaces `FACILITIES`, a fixed twelve-row array in
 * `packages/ui/src/content/academics.ts` whose photographs were the only
 * editable part - one CMS image field per row, generated by
 * `ACADEMICS_FACILITY_FIELDS` and keyed by `facilityImageFieldId`. Name, tag
 * and description were shipped copy no CMS editor could touch. This table
 * drops that split: every field including the list itself is now editable at
 * `/cms/facilities`, and `imageId` is the single photograph source - the old
 * per-facility block-image mechanism is gone, not kept as a fallback.
 *
 * `tag` is free text, not a CHECK-constrained set like
 * `alumniNotable.category`: the twelve shipped rows use six labels (Science,
 * Technology, Learning, Aesthetics, Community, Sport), but this is a category
 * an editor types on a new facility, not a fixed enum the product defines -
 * the College may add a facility that needs a seventh.
 *
 * `sortOrder` preserves the deliberate display order the shipped array had
 * (laboratories first, grounds and classrooms last) now that rows can be
 * added, removed and reordered without a deploy.
 */

export type FacilityId = Brand<string, "FacilityId">;
export const facilityIdSchema = v.pipe(
  v.string(),
  brand<string, "FacilityId">()
);

export const facility = sqliteTable(
  "facility",
  {
    id: text("id").primaryKey(),
    tag: text("tag").notNull(),
    name: text("name").notNull(),
    description: text("description"),
    imageId: text("image_id").references(() => files.id, {
      onDelete: "set null",
    }),
    sortOrder: integer("sort_order").notNull().default(0),
    publishedAt: integer("published_at", { mode: "timestamp_ms" }),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql.raw("(cast(unixepoch('subsecond') * 1000 as integer))"))
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .default(sql.raw("(cast(unixepoch('subsecond') * 1000 as integer))"))
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("facility_published_idx").on(table.publishedAt)]
);

export const facilitySelectSchema = createSelectSchema(facility, {
  id: () => facilityIdSchema,
});
export const facilityInsertSchema = createInsertSchema(facility, {
  id: () => facilityIdSchema,
});

export type Facility = v.InferOutput<typeof facilitySelectSchema>;
